-- Ocho tablas del dominio. IF NOT EXISTS conserva los datos al reiniciar.
CREATE TABLE IF NOT EXISTS rol (id_rol BIGINT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(30) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS usuario (id_usuario BIGINT AUTO_INCREMENT PRIMARY KEY, id_rol BIGINT NOT NULL, nombre VARCHAR(120) NOT NULL, correo VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(id_rol) REFERENCES rol(id_rol));
CREATE TABLE IF NOT EXISTS cargo (id_cargo BIGINT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(100) NOT NULL UNIQUE, descripcion VARCHAR(500) NOT NULL);
CREATE TABLE IF NOT EXISTS vacante (id_vacante BIGINT AUTO_INCREMENT PRIMARY KEY, id_cargo BIGINT NOT NULL, cupos INT NOT NULL CHECK(cupos > 0), fecha_apertura DATE NOT NULL, estado VARCHAR(10) NOT NULL CHECK(estado IN ('Abierta','Cerrada')), FOREIGN KEY(id_cargo) REFERENCES cargo(id_cargo));
CREATE TABLE IF NOT EXISTS candidato (id_candidato BIGINT AUTO_INCREMENT PRIMARY KEY, tipo_documento VARCHAR(10) NOT NULL, numero_documento VARCHAR(30) NOT NULL, nombres VARCHAR(80) NOT NULL, apellidos VARCHAR(80) NOT NULL, correo VARCHAR(150) NOT NULL, telefono VARCHAR(25) NOT NULL, fecha_registro TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_documento UNIQUE(tipo_documento,numero_documento));
CREATE TABLE IF NOT EXISTS estado_seleccion (id_estado BIGINT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(20) NOT NULL UNIQUE CHECK(nombre IN ('En proceso','Seleccionado','Rechazado')));
CREATE TABLE IF NOT EXISTS postulacion (id_postulacion BIGINT AUTO_INCREMENT PRIMARY KEY, id_candidato BIGINT NOT NULL, id_vacante BIGINT NOT NULL, id_estado BIGINT NOT NULL, fecha_postulacion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_postulacion UNIQUE(id_candidato,id_vacante), FOREIGN KEY(id_candidato) REFERENCES candidato(id_candidato), FOREIGN KEY(id_vacante) REFERENCES vacante(id_vacante), FOREIGN KEY(id_estado) REFERENCES estado_seleccion(id_estado));
CREATE TABLE IF NOT EXISTS historial_estado (id_historial BIGINT AUTO_INCREMENT PRIMARY KEY, id_postulacion BIGINT NOT NULL, id_estado BIGINT NOT NULL, id_usuario BIGINT NOT NULL, fecha_cambio TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, observacion VARCHAR(500) NOT NULL, FOREIGN KEY(id_postulacion) REFERENCES postulacion(id_postulacion), FOREIGN KEY(id_estado) REFERENCES estado_seleccion(id_estado), FOREIGN KEY(id_usuario) REFERENCES usuario(id_usuario));
